        let byte = s.char_indices().nth(i).map(|(b, _)| b).unwrap_or(s.len());
        s.truncate(byte);
    }
}

/// primary head の (行, 列[char数], 列[表示幅])。O(head)。
fn cursor_pos(text: &str, head: usize) -> (usize, usize, usize) {
    let mut row = 0usize;
    let mut col = 0usize;
    let mut colw = 0usize;
    for (i, ch) in text.chars().enumerate() {
        if i >= head {
            break;
        }
        if ch == '\n' {
            row += 1;
            col = 0;
            colw = 0;
